mapper.select:
SELECT *
FROM lunaerp_stock_in
WHERE id = #{id}
  AND deleted = 1
  AND status = 'DRAFT'
  AND tenant_id = #{tenantId}

mapper.update:
UPDATE lunaerp_stock_in
SET deleted = 0,
    status = 'DRAFT',
    updater = #{updater},
    update_time = #{updateTime}
WHERE id = #{id}
  AND deleted = 1
  AND status = 'DRAFT'
  AND tenant_id = #{tenantId}

mapper.delete:
DELETE FROM lunaerp_stock_in
WHERE id = #{id}
  AND deleted = 1
  AND status = 'DRAFT'
  AND tenant_id = #{tenantId}
